-- Seed dos 56 bairros oficiais de Florianópolis (Decreto 29.142/2026).
-- Polígonos simplificados alinhados aos nomes oficiais (Nominatim/OSM).
-- taxa null = bairro ainda não atendido.

set search_path = public, extensions;
-- Seed bairros oficiais Florianópolis (Decreto 29.142/2026)
-- Geometrias simplificadas (Nominatim/OSM) alinhadas aos nomes oficiais.
on conflict (slug) do update set
  nome = excluded.nome,
  regiao = excluded.regiao,
  distrito = excluded.distrito,
  geom = excluded.geom,
  atualizado_em = now();

